score::Version lo = *minv;
score::Version hi = *maxv;

// Enforce precondition: min <= max
if (!(lo <= hi)) { FUZZ_BAIL(); }

// Invoke clamp; return type deduces to score::Version
auto r = clamp(v, lo, hi);

// Validate clamping properties
// Result must be within [lo, hi]
FUZZ_ASSERT(!(r < lo) && !(r > hi), "clamp result out of bounds");

// Edge cases: if v < lo then r == lo; if v > hi then r == hi; otherwise r == v
if (v < lo) {
  FUZZ_ASSERT(r == lo, "clamp did not return min when below range");
} else if (v > hi) {
  FUZZ_ASSERT(r == hi, "clamp did not return max when above range");
} else {
  FUZZ_ASSERT(r == v, "clamp did not return value when within range");
}

// Validation: Inputs are preserved and returned to the pool; all API constraints checked, including min<=max and postconditions.

